O=Path(__file__).parent;p=O/'front_sections_pixel_candidates.json';q=O/'nose_to_A_stroke_center_samples.json';j=json.loads(p.read_text());a=next(v for v in j['profiles'] if v['section']=='A')['loops_pixel'][0];rawW=max(v[0] for v in a)-min(v[0] for v in a);rawH=max(v[1] for v in a)-min(v[1] for v in a);t=json.loads(q.read_text())['samples'][-1];W=t['width_candidate_mm'];H=t['height_candidate_mm']
